item.command:
/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic a,
    input  logic b,
    output logic q
);
    assign q = a & b;
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic a, b;
    wire q;
    integer source_pair, target_pair;
    integer checks = 0;
    TopModule dut (.a(a), .b(b), .q(q));

    task automatic check_pair(input integer pair_index);
        logic expected;
        begin
            case (pair_index)
                0: begin a = 0; b = 0; expected = 0; end
                1: begin a = 0; b = 1; expected = 0; end
                2: begin a = 1; b = 0; expected = 0; end
                3: begin a = 1; b = 1; expected = 1; end
                default: $fatal(1, "Invalid test input");
            endcase
            #1;
            if (q !== expected)
                $fatal(1, "FAIL a=%b b=%b q=%b expected=%b", a, b, q, expected);
            checks = checks + 1;
        end
    endtask

    initial begin
        for (source_pair = 0; source_pair < 4; source_pair = source_pair + 1)
            for (target_pair = 0; target_pair < 4; target_pair = target_pair + 1) begin
                check_pair(source_pair);
                check_pair(target_pair);
            end
        $display("PASS: %0d checks, all four input pairs and sixteen pair transitions", checks);
        $finish;
    end
    initial begin
        #100;
        $fatal(1, "FAIL: testbench timeout");
    end
endmodule
EOF
 timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > dev_compile.log 2>&1
compile_status=$?
if [ "$compile_status" -eq 0 ]; then
    timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > dev_simulation.log 2>&1
    sim_status=$?
else
    sim_status=125
fi
python3 - "$compile_status" "$sim_status" <<'"'PY'
import json,sys
from pathlib import Path
compile_status, sim_status = map(int,sys.argv[1:])
passed = compile_status == 0 and sim_status == 0 and 'PASS:' in Path('dev_simulation.log').read_text()
report = {'revision_count':0,'checks':[{'name':'frozen contract structural gate','result':'passed_structure_only','log':'contract_validation.log'},{'name':'Icarus -g2012 -Wall explicit dev_tb elaboration','exit_code':compile_status,'log':'dev_compile.log'},{'name':'exhaustive binary truth table and all sixteen transitions','exit_code':sim_status,'log':'dev_simulation.log','result':'passed' if passed else 'failed_or_unavailable'}],'development_outcome':'PASS' if passed else 'Development check failed; best initial RTL retained','limitations':['Official evaluation has not run during this turn.','X/Z behavior is unspecified by the original problem.','No synthesis, physical timing, or board validation performed.'],'contract_corrections':[],'static_review':'Single continuous assignment; exact ports and widths; no state, latches, delays, or external dependencies.'}
Path('worker_report.json').write_text(json.dumps(report,indent=2)+'\\n')
PY
cat dev_compile.log dev_simulation.log worker_report.json"

